import React, { useEffect, useState } from 'react';
import { db } from '../firebase';
import { doc, updateDoc, increment, setDoc, onSnapshot, collection, addDoc } from 'firebase/firestore';
import { motion, AnimatePresence } from 'framer-motion';
import { FaStar } from 'react-icons/fa';

import StarFieldOverlay from './StarFieldOverlay';

const VisitorCounter = () => {
    const [count, setCount] = useState(null);
    const [error, setError] = useState(false);
    const [isOverlayOpen, setIsOverlayOpen] = useState(false);

    useEffect(() => {
        const statsRef = doc(db, 'stats', 'visitors');

        const updateCounter = async () => {
            try {
                // Increment only once per session
                if (!sessionStorage.getItem('nebula_visited')) {
                    // Fetch location data
                    let locationData = {};

                    // 1. Get Location
                    try {
                        const controller = new AbortController();
                        const timeoutId = setTimeout(() => controller.abort(), 3000);
                        const response = await fetch('https://ipapi.co/json/', { signal: controller.signal });
                        clearTimeout(timeoutId);
                        if (response.ok) {
                            const data = await response.json();
                            locationData = {
                                country: data.country_name || 'Unknown',
                                countryCode: data.country_code || 'XX',
                                city: data.city || 'Unknown',
                                region: data.region || 'Unknown',
                                ip: data.ip || 'Unknown',
                            };
                        }
                    } catch (err) {
                        // Ignore location fetch timeout or network failure gracefully
                    }

                    // 2. Get Device/Browser Info
                    const ua = navigator.userAgent;
                    let browser = 'Unknown';
                    let os = 'Unknown';
                    let deviceType = 'Desktop';

                    // Simple Browser Detection
                    if (ua.indexOf("Firefox") > -1) browser = "Firefox";
                    else if (ua.indexOf("SamsungBrowser") > -1) browser = "Samsung Internet";
                    else if (ua.indexOf("Opera") > -1 || ua.indexOf("OPR") > -1) browser = "Opera";
                    else if (ua.indexOf("Trident") > -1) browser = "Internet Explorer";
                    else if (ua.indexOf("Edge") > -1) browser = "Edge";
                    else if (ua.indexOf("Chrome") > -1) browser = "Chrome";
                    else if (ua.indexOf("Safari") > -1) browser = "Safari";

                    // Simple OS Detection
                    if (ua.indexOf("Win") > -1) os = "Windows";
                    else if (ua.indexOf("Mac") > -1) os = "MacOS";
                    else if (ua.indexOf("Linux") > -1) os = "Linux";
                    else if (ua.indexOf("Android") > -1) os = "Android";
                    else if (ua.indexOf("like Mac") > -1) os = "iOS";

                    // Simple Device Type Detection
                    if (/Mobi|Android/i.test(ua)) {
                        deviceType = 'Mobile';
                    } else if (/iPad|Tablet/i.test(ua)) {
                        deviceType = 'Tablet';
                    }

                    const visitData = {
                        ...locationData,
                        browser,
                        os,
                        deviceType,
                        screenResolution: `${window.screen.width}x${window.screen.height}`,
                        timestamp: new Date(),
                        path: window.location.hash || '/'
                    };

                    // Update visitor count
                    await updateDoc(statsRef, { count: increment(1) }).catch(async (err) => {
                        // If doc doesn't exist, create it
                        if (err.code === 'not-found') {
                            await setDoc(statsRef, { count: 1 });
                        } else {
                            throw err;
                        }
                    });

                    // Store location data in visitor_logs collection
                    try {
                        await addDoc(collection(db, 'visitor_logs'), visitData);
                    } catch (err) {
                        console.error("Error storing visit log:", err);
                    }

                    sessionStorage.setItem('nebula_visited', 'true');
                }
            } catch (err) {
                console.error("Firebase Connection Error:", err.message);
                setError(true);
            }
        };

        updateCounter();

        // Real-time listener
        const unsubscribe = onSnapshot(statsRef, (doc) => {
            if (doc.exists()) {
                setCount(doc.data().count);
            }
        }, (err) => {
            console.error("Firestore Listen Error:", err.code);
            setError(true);
        });

        return () => {
            if (typeof unsubscribe === 'function') unsubscribe();
        };
    }, []);

    const getOrdinal = (n) => {
        const s = ["th", "st", "nd", "rd"];
        const v = n % 100;
        return s[(v - 20) % 10] || s[v] || s[0];
    };

    if (error || count === null) return null;

    return (
        <>
            <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 1.5, delay: 0.5 }}
                style={{
                    marginTop: '0.75rem',
                    display: 'flex',
                    justifyContent: 'center'
                }}
            >
                <motion.div
                    onClick={() => setIsOverlayOpen(true)}
                    whileHover={{
                        scale: 1.05,
                        background: 'rgba(255, 255, 255, 0.03)',
                        borderColor: 'rgba(255, 255, 255, 0.1)'
                    }}
                    whileTap={{ scale: 0.95 }}
                    style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: '10px',
                        padding: '6px 16px',
                        background: 'rgba(255, 255, 255, 0.01)',
                        backdropFilter: 'blur(5px)',
                        borderRadius: '20px',
                        border: '1px solid rgba(255, 255, 255, 0.03)',
                        color: 'var(--text-secondary)',
                        fontSize: '0.75rem',
                        fontFamily: 'var(--font-mono)',
                        letterSpacing: '0.5px',
                        cursor: 'pointer',
                        transition: 'background 0.3s ease, border-color 0.3s ease'
                    }}
                >
                    <motion.div
                        animate={{
                            opacity: [0.3, 0.8, 0.3],
                        }}
                        transition={{
                            duration: 4,
                            repeat: Infinity,
                            ease: "easeInOut"
                        }}
                        style={{ color: 'var(--accent-color)', display: 'flex' }}
                    >
                        <FaStar size={10} />
                    </motion.div>
                    <span>
                        You are the <span style={{ color: 'var(--accent-color)', fontWeight: '600' }}>{count}</span>
                        <sup style={{ fontSize: '0.55rem', opacity: 0.8, marginLeft: '1px' }}>
                            {getOrdinal(count)}
                        </sup> star to drift through this digital nebula
                        {/* star in this nebula */}
                    </span>
                </motion.div>
            </motion.div>

            <AnimatePresence>
                {isOverlayOpen && (
                    <StarFieldOverlay
                        count={count}
                        onClose={() => setIsOverlayOpen(false)}
                    />
                )}
            </AnimatePresence>
        </>
    );
};

export default VisitorCounter;
